"""
Hardcoded NIPUN FLN activity bank for Grades 1–3.
Questions, cards, worksheets and games are real classroom items — not
keyword soup from a failed SLM. Strings are localized for all 7 classroom languages.
"""

from typing import Any, Dict, List

LANGS = ("en", "hi", "sat", "bn", "mr", "ta", "te")


def loc(table: Dict[str, str], lang: str) -> str:
    return table.get(lang) or table.get("en") or next(iter(table.values()), "")


def _domain_for_subject(subject: str) -> str:
    s = (subject or "Mathematics").lower()
    if any(x in s for x in ("math", "गणित", "ᱮᱞᱠᱷᱟ", "গণিত", "கணிதம்", "గణిత")):
        return "math"
    if any(x in s for x in ("literacy", "language", "भाषा", "ᱚᱞ", "ভাষা", "மொழி", "భాష", "reading")):
        return "literacy"
    if any(x in s for x in ("science", "evs", "पर्यावरण", "ᱯᱚᱨᱤᱵᱮᱥ", "বিজ্ঞান", "அறிவியல்", "సైన్స్")):
        return "science"
    return "general"


def _grade(g: int) -> int:
    if g <= 1:
        return 1
    if g >= 3:
        return 3
    return 2


# ── Quizzes ──────────────────────────────────────────────────────────────────

def _q(visual: str, question: Dict[str, str], options: List[Dict[str, str]], correct_idx: int, hint: Dict[str, str], expl: Dict[str, str]) -> Dict[str, Any]:
    return {
        "visual": visual,
        "question": question,
        "options": options,
        "correct_idx": correct_idx,
        "hint": hint,
        "expl": expl,
    }


