def _quiz_pool(domain: str, grade: int) -> List[Dict[str, Any]]:
    g = _grade(grade)
    if domain == "math":
        return MATH_QUIZ[g]
    if domain == "literacy":
        # reuse grade 1 bank for 2/3 with extra harder items from math-adjacent literacy
        return LIT_QUIZ[1]
    if domain == "science":
        return SCI_QUIZ[1]
    return GK_QUIZ[1]


def build_quiz(grade: int, lang: str, subject: str) -> Dict[str, Any]:
    domain = _domain_for_subject(subject)
    pool = _quiz_pool(domain, grade)
    questions = []
    for i, item in enumerate(pool):
        opts = [loc(o if "en" in o or len(o) > 1 else {"en": o.get("en", list(o.values())[0])}, lang) if False else loc(o, lang) for o in item["options"]]
        # loc() already handles {"en": "5"} by falling back to en
        opts = [loc(o, lang) for o in item["options"]]
        correct = opts[item["correct_idx"]]
        questions.append({
            "id": f"q{i+1}",
            "question": loc(item["question"], lang),
            "options": opts,
            "correct": correct,
            "visual": item["visual"],
            "hint": loc(item["hint"], lang),
            "explanation": loc(item["expl"], lang),
            "difficulty": ["EASY", "EASY", "MEDIUM", "MEDIUM", "HARD"][i],
            "points": [10, 10, 15, 15, 20][i],
            "domain": domain,
            "nipun_skill": {
                "math": "Numeracy",
                "literacy": "Literacy",
                "science": "EVS",
                "general": "General Knowledge",
            }[domain],
        })
    titles = {
        "math": {"en": "Maths Quiz", "hi": "गणित प्रश्नोत्तरी", "sat": "ᱮᱞᱠᱷᱟ ᱠᱩᱠᱞᱤ", "bn": "গণিত কুইজ", "mr": "गणित प्रश्नोत्तरी", "ta": "கணித வினாடி வினா", "te": "గణిత క్విజ్"},
        "literacy": {"en": "Language Quiz", "hi": "भाषा प्रश्नोत्तरी", "sat": "ᱯᱟᱹᱨᱥᱤ ᱠᱩᱠᱞᱤ", "bn": "ভাষা কুইজ", "mr": "भाषा प्रश्नोत्तरी", "ta": "மொழி வினாடி வினா", "te": "భాషా క్విజ్"},
        "science": {"en": "EVS Quiz", "hi": "पर्यावरण प्रश्नोत्तरी", "sat": "ᱯᱚᱨᱤᱵᱮᱥ ᱠᱩᱠᱞᱤ", "bn": "পরিবেশ কুইজ", "mr": "पर्यावरण प्रश्नोत्तरी", "ta": "சூழலியல் வினாடி வினா", "te": "పరిసరాల క్విజ్"},
        "general": {"en": "GK Quiz", "hi": "सामान्य ज्ञान", "sat": "ᱥᱟᱫᱷᱟᱨᱚᱱ ᱡᱟᱱᱟᱢ", "bn": "সাধারণ জ্ঞান", "mr": "सामान्य ज्ञान", "ta": "பொது அறிவு", "te": "సాధారణ పరిజ్ఞానం"},
    }
    grade_l = {"en": f"Grade {grade}", "hi": f"कक्षा {grade}", "sat": f"ᱪᱟᱱᱟᱪ {grade}", "bn": f"শ্রেণী {grade}", "mr": f"वर्ग {grade}", "ta": f"வகுப்பு {grade}", "te": f"తరగతి {grade}"}
    return {
        "title": f"{loc(grade_l, lang)} {loc(titles[domain], lang)}",
        "questions": questions,
    }


